#include "stdafx.h"
#include "ToolbarLayoutAdapter.h"
void ToolbarLayoutAdapter::Capture(HWND toolbar, std::vector<PortableToolbarItem>& items) { items.clear(); CToolBarCtrl source = toolbar; for(int index = 0; index < source.GetButtonCount(); ++index) { TBBUTTON button = {}; if(!source.GetButton(index, &button)) continue; PortableToolbarItem item = {}; item.separator = (button.fsStyle & TBSTYLE_SEP) != 0; item.command = button.idCommand; item.width = button.iBitmap; items.push_back(item); } }
void ToolbarLayoutAdapter::Apply(HWND toolbar, const std::vector<PortableToolbarItem>& items, const std::vector<TBBUTTON>& catalog) { CToolBarCtrl target = toolbar; std::vector<TBBUTTON> restored; for(size_t index = 0; index < items.size(); ++index) { const PortableToolbarItem& item = items[index]; if(item.separator) { TBBUTTON separator = {}; separator.iBitmap = item.width > 0 ? item.width : 8; separator.fsStyle = TBSTYLE_SEP; restored.push_back(separator); continue; } for(size_t buttonIndex = 0; buttonIndex < catalog.size(); ++buttonIndex) if(catalog[buttonIndex].idCommand == item.command) { restored.push_back(catalog[buttonIndex]); break; } } while(target.GetButtonCount() > 0) target.DeleteButton(0); if(!restored.empty()) target.AddButtons(static_cast<int>(restored.size()), &restored[0]); target.AutoSize(); }
